        <section style={{ background: '#0e1526', padding: '20px', borderRadius: '10px', border: '1px solid #1e293b', height: 'fit-content' }}>
          <h2 style={{ fontSize: '16px', margin: '0 0 16px', color: '#f1f5f9' }}>Create Device</h2>
          <form onSubmit={handleCreate}>
